442	bool PhysicsWorld::init()
443	{
444	    do
445	    {
446	#if CC_TARGET_PLATFORM == CC_PLATFORM_WIN32
447			_cpSpace = cpSpaceNew();
448	#else
449	        _cpSpace = cpHastySpaceNew();
450	        cpHastySpaceSetThreads(_cpSpace, 0);
451	#endif
452	        CC_BREAK_IF(_cpSpace == nullptr);
453	        
454	        cpSpaceSetGravity(_cpSpace, PhysicsHelper::point2cpv(_gravity));
455	        
456	        cpCollisionHandler *handler = cpSpaceAddDefaultCollisionHandler(_cpSpace);
457	        handler->userData = this;
458	        handler->beginFunc = (cpCollisionBeginFunc)PhysicsWorldCallback::collisionBeginCallbackFunc;
459	        handler->preSolveFunc = (cpCollisionPreSolveFunc)PhysicsWorldCallback::collisionPreSolveCallbackFunc;
460	        handler->postSolveFunc = (cpCollisionPostSolveFunc)PhysicsWorldCallback::collisionPostSolveCallbackFunc;
461	        handler->separateFunc = (cpCollisionSeparateFunc)PhysicsWorldCallback::collisionSeparateCallbackFunc;
462	        
463	        return true;
464	    } while (false);
465	    
466	    return false;
467	}
