469	void PhysicsWorld::addBody(PhysicsBody* body)
470	{
471	    CCASSERT(body != nullptr, "the body can not be nullptr");
472	    
473	    if (body->getWorld() == this)
474	    {
475	        return;
476	    }
477	    
478	    if (body->getWorld() != nullptr)
479	    {
