629	void PhysicsWorld::doRemoveBody(PhysicsBody* body)
630	{
631	    CCASSERT(body != nullptr, "the body can not be nullptr");
632	    
633	    // remove shapes
634	    for (auto& shape : body->getShapes())
635	    {
636	        removeShape(shape);
637	    }
638	    
639	    // remove body
640	    if (cpSpaceContainsBody(_cpSpace, body->_cpBody))
641	    {
642	        cpSpaceRemoveBody(_cpSpace, body->_cpBody);
643	    }
644	}
