646	void PhysicsWorld::doRemoveJoint(PhysicsJoint* joint)
647	{
648	    for (auto constraint : joint->_cpConstraints)
649	    {
650	        cpSpaceRemoveConstraint(_cpSpace, constraint);
651	    }
652	    _joints.remove(joint);
653	    joint->_world = nullptr;
654	
655	    if (joint->getBodyA())
656	    {
657	        joint->getBodyA()->removeJoint(joint);
658	    }
659	
660	    if (joint->getBodyB())
661	    {
662	        joint->getBodyB()->removeJoint(joint);
663	    }
664	
665	    if (joint->_destroyMark)
666	    {
667	        delete joint;
668	    }
